using System.Globalization;
using System.Text;
using BinaryParser;
using TableAutomationTool.Common.Utils;
using TableAutomationTool.UserEnum;

namespace TableAutomationTool.Generator.CodeGenerator
{
    public struct CSharpInfoParam
    {
        /// <summary>테이블 코드(Template/Info/InfoManager/InfoHandler) 출력 폴더</summary>
        public string infoRootDirectory;
        /// <summary>DataManager 폴더. Base/DataManagerAutoGenerated.cs 를 여기에 쓴다. 비면 infoRootDirectory.</summary>
        public string managerRootDirectory;
        public string @namespace;
    }

    /// <summary>
    /// Binary 스키마로 Unity 클라이언트의 Info 구조를 생성한다.
    ///
    ///   {root}/{T}InfoTemplate.cs                  : 데이터 원본         (매번 재생성)
    ///   {root}/{T}Info.cs                          : 커스텀 로직         (최초 1회)
    ///   {root}/{T}InfoManager.cs                   : 테이블 로딩         (최초 1회)
    ///   {root}/{T}InfoHandler.cs                   : 조회 래퍼           (최초 1회)
    ///   {root}/Base/DataManagerAutoGenerated.cs    : InfoManager 등록부  (매번 재생성)
    ///
    /// {T} 는 .bin 이름(= 워크시트 이름), 키는 첫 번째 컬럼이다.
    /// 베이스 타입(InfoManagerBase, IInfoTemplate, InfoRow 등)은 {root}/Base 에 수작업으로 둔다.
    ///
    /// Const 테이블(SystemConst, 컬럼 Class | Key | Type | Value)은 행 데이터로 코드를 만든다.
    ///   {root}/{T}InfoTemplate.cs                  : 상수 선언(static class {T}.{Class}.{Key}),
    ///                                                행 클래스 {T}Info, 로더 {T}InfoManager (매번 재생성)
    /// Info/InfoManager/InfoHandler 사용자 파일은 만들지 않는다.
    /// </summary>
    public class CSharpInfoGenerator
    {
        private const string BaseFolder = "Base";
        private const string DataManagerFileName = "DataManagerAutoGenerated.cs";
        private const string ConstTableName = "SystemConst";
        private static readonly string[] ConstColumns = { "Class", "Key", "Type", "Value" };
        private static readonly string[] ConstSupportedTypes = { "int", "long", "float", "double", "bool", "string" };

        /// <summary>키워드 목록에는 없지만 식별자로 쓸 수 없는 컴파일러 예약 토큰</summary>
        private static readonly string[] CSharpReservedTokens = { "__arglist", "__makeref", "__reftype", "__refvalue" };

        private static readonly HashSet<string> CSharpKeywords = new(StringComparer.Ordinal)
        {
            "abstract", "as", "base", "bool", "break", "byte", "case", "catch", "char", "checked", "class", "const",
            "continue", "decimal", "default", "delegate", "do", "double", "else", "enum", "event", "explicit",
            "extern", "false", "finally", "fixed", "float", "for", "foreach", "goto", "if", "implicit", "in", "int",
            "interface", "internal", "is", "lock", "long", "namespace", "new", "null", "object", "operator", "out",
            "override", "params", "private", "protected", "public", "readonly", "ref", "return", "sbyte", "sealed",
            "short", "sizeof", "stackalloc", "static", "string", "struct", "switch", "this", "throw", "true", "try",
            "typeof", "uint", "ulong", "unchecked", "unsafe", "ushort", "using", "virtual", "void", "volatile", "while",
        };

        private readonly CSharpInfoParam _param;

        public CSharpInfoGenerator(CSharpInfoParam param)
        {
            _param = param;
        }

        /// <summary>
        /// 테이블 1개의 Template(재생성)과 Info/InfoManager/InfoHandler(없을 때만)를 만든다.
        /// Const 테이블은 Template 1개(재생성)만 만든다.
        /// </summary>
        public bool GenerateTable(string binaryFilePath)
        {
            if (IsConstTable(Path.GetFileNameWithoutExtension(binaryFilePath) ?? ""))
                return GenerateConstTable(binaryFilePath);

            if (!TryReadTable(binaryFilePath, out var table))
                return false;

            var root = _param.infoRootDirectory;
            Directory.CreateDirectory(root);
            WriteAlways(Path.Combine(root, $"{table.Name}InfoTemplate.cs"), BuildTemplate(table));
            WriteIfMissing(Path.Combine(root, $"{table.Name}Info.cs"), BuildInfo(table));
            WriteIfMissing(Path.Combine(root, $"{table.Name}InfoManager.cs"), BuildInfoManager(table));
            WriteIfMissing(Path.Combine(root, $"{table.Name}InfoHandler.cs"), BuildInfoHandler(table));
            return true;
        }

        /// <summary>
        /// Const 테이블은 Key 목록이 행 데이터에 있으므로 선언·로더를 모두 Template 파일 하나에 넣어 매번 재생성한다.
        /// 파일이 하나라 .bin 이 없어지면 기존 RemoveStaleTemplates 가 함께 지운다.
        /// </summary>
        private bool GenerateConstTable(string binaryFilePath)
        {
            var tableName = Path.GetFileNameWithoutExtension(binaryFilePath);
            Logger.Instance.Log($"[CSharpInfoGenerator] Const table: {tableName}");

            // 일반 경로로 생성된 사용자 파일은 같은 이름의 타입({T}Info, {T}InfoManager)을 선언하므로 컴파일이 깨진다.
            // 사용자 파일이라 지우지 않고 멈춘다.
            var root = _param.infoRootDirectory;
            var legacyFiles = new[] { $"{tableName}Info.cs", $"{tableName}InfoManager.cs" }
                .Select(name => Path.Combine(root, name))
                .Where(File.Exists)
                .ToList();
            if (legacyFiles.Count > 0)
            {
                Logger.Instance.Error($"[CSharpInfoGenerator] {tableName} is a const table, but normal-table files exist: {string.Join(", ", legacyFiles)}. Delete them (with .meta) and generate again.");
                return false;
            }

            if (!TryReadConstTable(binaryFilePath, out var schema))
                return false;

            Directory.CreateDirectory(root);
            WriteAlways(Path.Combine(root, $"{schema.TableName}InfoTemplate.cs"), BuildConstTemplate(schema));
            return true;
        }

        /// <summary>
        /// 전체 테이블 목록으로 DataManagerAutoGenerated.cs 를 다시 만든다.
        /// -each 로 일부만 생성할 때도 등록부는 전체 목록 기준이어야 하므로 항상 모든 .bin 을 받는다.
        /// </summary>
        public void GenerateDataManager(IEnumerable<string> allBinaryFilePaths)
        {
            var tableNames = allBinaryFilePaths
                .Select(Path.GetFileNameWithoutExtension)
                .OfType<string>()
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(n => n, StringComparer.Ordinal)
                .ToList();

            var managerRoot = string.IsNullOrWhiteSpace(_param.managerRootDirectory)
                ? _param.infoRootDirectory
                : _param.managerRootDirectory;
            var directory = Path.Combine(managerRoot, BaseFolder);
            Directory.CreateDirectory(directory);
            WriteAlways(Path.Combine(directory, DataManagerFileName), BuildDataManager(tableNames));
        }

        /// <summary>
        /// 더 이상 .bin 이 없는 테이블의 Template 을 지운다. (전체 생성 시에만 호출)
        /// Info/InfoManager/InfoHandler 등 사용자 파일은 건드리지 않는다.
        /// </summary>
        public void RemoveStaleTemplates(IEnumerable<string> allBinaryFilePaths)
        {
            var root = _param.infoRootDirectory;
            if (!Directory.Exists(root))
                return;

            var expected = new HashSet<string>(
                allBinaryFilePaths.Select(p => $"{Path.GetFileNameWithoutExtension(p)}InfoTemplate.cs"),
                StringComparer.OrdinalIgnoreCase);

            foreach (var file in Directory.GetFiles(root, "*InfoTemplate.cs"))
            {
                if (expected.Contains(Path.GetFileName(file)))
                    continue;

                File.Delete(file);
                var meta = file + ".meta";
                if (File.Exists(meta))
                    File.Delete(meta);
                Logger.Instance.Log($"[CSharpInfoGenerator] Removed stale template: {file}");
            }
        }

        // ============================================================
        // Builders
        // ============================================================

        private string BuildTemplate(TableSchema table)
        {
            var sb = new StringBuilder();
            AppendAutoGeneratedHeader(sb, "매번 재생성됩니다. 수정하지 마세요. 커스텀 로직은 " + $"{table.Name}Info.cs 에 작성합니다.");
            foreach (var usingNamespace in CollectTemplateUsings(table))
                sb.AppendLine($"using {usingNamespace};");
            sb.AppendLine();
            sb.AppendLine($"namespace {_param.@namespace}");
            sb.AppendLine("{");
            sb.AppendLine("    /// <summary>");
            sb.AppendLine($"    /// {table.Name} 테이블 데이터 원본");
            sb.AppendLine("    /// </summary>");
            sb.AppendLine($"    public class {table.Name}InfoTemplate : IInfoTemplate<{table.KeyType}>");
            sb.AppendLine("    {");

            foreach (var column in table.Columns)
                sb.AppendLine($"        public {column.Type} {column.Name} {{ get; private set; }}");
            sb.AppendLine();

            sb.AppendLine($"        protected {table.Name}InfoTemplate()");
            sb.AppendLine("        {");
            sb.AppendLine("        }");
            sb.AppendLine();

            sb.AppendLine($"        public {table.Name}InfoTemplate(");
            sb.AppendLine(string.Join(",\n", table.Columns.Select(c => $"            {c.Type} {c.ParameterName}")));
            sb.AppendLine("        )");
            sb.AppendLine("        {");
            foreach (var column in table.Columns)
                sb.AppendLine($"            {column.Name} = {column.ParameterName};");
            sb.AppendLine("        }");
            sb.AppendLine();

            sb.AppendLine($"        {table.KeyType} IInfoTemplate<{table.KeyType}>.InfoKey => {table.Columns[0].Name};");
            sb.AppendLine();

            sb.AppendLine($"        void IInfoTemplate<{table.KeyType}>.Deserialize(InfoRow row)");
            sb.AppendLine("        {");
            foreach (var column in table.Columns)
                sb.AppendLine($"            {column.Name} = row.Get<{column.Type}>(\"{column.Name}\");");
            sb.AppendLine("        }");

            sb.AppendLine("    }");
            sb.AppendLine("}");
            return sb.ToString();
        }

        /// <summary>
        /// Template 파일의 using 목록. System 과, 칼럼에 쓰인 enum 이 선언된 네임스페이스(EnumDB 기준)를 넣는다.
        /// </summary>
        private IEnumerable<string> CollectTemplateUsings(TableSchema table)
        {
            var enumNamespaces = new SortedSet<string>(StringComparer.Ordinal);
            foreach (var column in table.Columns)
            {
                var elementType = column.Type.EndsWith("[]") ? column.Type[..^2] : column.Type;
                var enumNamespace = EnumDB.Instance.GetEnumNamespace(elementType);
                if (!string.IsNullOrEmpty(enumNamespace) && enumNamespace != _param.@namespace && enumNamespace != "System")
                    enumNamespaces.Add(enumNamespace);
            }
            return enumNamespaces.Prepend("System");
        }

        private string BuildInfo(TableSchema table)
        {
            var sb = new StringBuilder();
            AppendOnceHeader(sb);
            sb.AppendLine($"namespace {_param.@namespace}");
            sb.AppendLine("{");
            sb.AppendLine("    /// <summary>");
            sb.AppendLine($"    /// {table.Name} 테이블 데이터. 프로젝트 전용 로직을 여기에 추가한다.");
            sb.AppendLine("    /// </summary>");
            sb.AppendLine($"    public partial class {table.Name}Info : {table.Name}InfoTemplate, IInfoValidateChecker");
            sb.AppendLine("    {");
            sb.AppendLine("        public bool IsValidData()");
            sb.AppendLine("        {");
            sb.AppendLine("            return true;");
            sb.AppendLine("        }");
            sb.AppendLine();
            sb.AppendLine("        public bool IsValidAfterLoad()");
            sb.AppendLine("        {");
            sb.AppendLine("            return true;");
            sb.AppendLine("        }");
            sb.AppendLine("    }");
            sb.AppendLine("}");
            return sb.ToString();
        }

        private string BuildInfoManager(TableSchema table)
        {
            var sb = new StringBuilder();
            AppendOnceHeader(sb);
            sb.AppendLine($"namespace {_param.@namespace}");
            sb.AppendLine("{");
            sb.AppendLine("    /// <summary>");
            sb.AppendLine($"    /// {table.Name} 테이블 로딩/보관");
            sb.AppendLine("    /// </summary>");
            sb.AppendLine($"    public partial class {table.Name}InfoManager : InfoManagerBase<{table.KeyType}, {table.Name}Info>");
            sb.AppendLine("    {");
            sb.AppendLine($"        public override string TableName => \"{table.Name}\";");
            sb.AppendLine("    }");
            sb.AppendLine("}");
            return sb.ToString();
        }

        private string BuildInfoHandler(TableSchema table)
        {
            var sb = new StringBuilder();
            AppendOnceHeader(sb);
            sb.AppendLine($"namespace {_param.@namespace}");
            sb.AppendLine("{");
            sb.AppendLine("    /// <summary>");
            sb.AppendLine($"    /// {table.Name} 데이터 조회 진입점");
            sb.AppendLine("    /// </summary>");
            sb.AppendLine($"    public static partial class {table.Name}InfoHandler");
            sb.AppendLine("    {");
            sb.AppendLine($"        public static {table.Name}Info GetData({table.KeyType} id)");
            sb.AppendLine("        {");
            sb.AppendLine($"            return DataManager.Instance.{table.Name}InfoManager.GetData(id);");
            sb.AppendLine("        }");
            sb.AppendLine();
            sb.AppendLine($"        public static bool TryGetData({table.KeyType} id, out {table.Name}Info info)");
            sb.AppendLine("        {");
            sb.AppendLine($"            return DataManager.Instance.{table.Name}InfoManager.TryGetData(id, out info);");
            sb.AppendLine("        }");
            sb.AppendLine("    }");
            sb.AppendLine("}");
            return sb.ToString();
        }

        private string BuildDataManager(IReadOnlyList<string> tableNames)
        {
            var sb = new StringBuilder();
            AppendAutoGeneratedHeader(sb, "매번 재생성됩니다. 수정하지 마세요. 로딩 흐름은 Base/DataManager.cs 에 있습니다.");
            sb.AppendLine("using System.Collections.Generic;");
            sb.AppendLine();
            sb.AppendLine($"namespace {_param.@namespace}");
            sb.AppendLine("{");
            sb.AppendLine("    public partial class DataManager");
            sb.AppendLine("    {");
            sb.AppendLine("        // ============================================================");
            sb.AppendLine("        // Members");
            sb.AppendLine("        // ============================================================");
            foreach (var name in tableNames)
                sb.AppendLine($"        public {name}InfoManager {name}InfoManager {{ get; }} = new {name}InfoManager();");
            if (tableNames.Count > 0)
                sb.AppendLine();

            sb.AppendLine("        /// <summary>");
            sb.AppendLine("        /// 등록된 모든 InfoManager");
            sb.AppendLine("        /// </summary>");
            sb.AppendLine("        public IEnumerable<IInfoManager> InfoManagers");
            sb.AppendLine("        {");
            sb.AppendLine("            get");
            sb.AppendLine("            {");
            foreach (var name in tableNames)
                sb.AppendLine($"                yield return {name}InfoManager;");
            if (tableNames.Count == 0)
                sb.AppendLine("                yield break;");
            sb.AppendLine("            }");
            sb.AppendLine("        }");
            sb.AppendLine();

            sb.AppendLine("        // ============================================================");
            sb.AppendLine("        // Methods");
            sb.AppendLine("        // ============================================================");
            sb.AppendLine();
            sb.AppendLine("        /// <summary>");
            sb.AppendLine("        /// 모든 테이블을 동기 로딩합니다.");
            sb.AppendLine("        /// </summary>");
            sb.AppendLine("        private bool LoadAll()");
            sb.AppendLine("        {");
            sb.AppendLine("            bool isSuccess = true;");
            foreach (var name in tableNames)
                sb.AppendLine($"            isSuccess &= {name}InfoManager.Load();");
            sb.AppendLine("            return isSuccess;");
            sb.AppendLine("        }");
            sb.AppendLine();
            sb.AppendLine("        /// <summary>");
            sb.AppendLine("        /// 모든 테이블 로딩 후 테이블 간 검사를 진행합니다.");
            sb.AppendLine("        /// </summary>");
            sb.AppendLine("        private bool DoAfterLoad()");
            sb.AppendLine("        {");
            sb.AppendLine("            bool isSuccess = true;");
            foreach (var name in tableNames)
                sb.AppendLine($"            isSuccess &= {name}InfoManager.DoAfterLoad();");
            sb.AppendLine("            return isSuccess;");
            sb.AppendLine("        }");
            sb.AppendLine("    }");
            sb.AppendLine("}");
            return sb.ToString();
        }

        /// <summary>
        /// Const 테이블 Template. 클라이언트 Base(InfoManagerBase)의 로딩·캐시·중복 키 검사를 그대로 쓰고,
        /// 로드가 끝나면(OnLoaded) 생성된 각 상수에 (Class, Key) 행의 Value 를 코드 타입으로 파싱해 넣는다.
        /// </summary>
        private string BuildConstTemplate(ConstTableSchema schema)
        {
            var t = schema.TableName;
            var sb = new StringBuilder();
            AppendAutoGeneratedHeader(sb, $"매번 재생성됩니다. 수정하지 마세요. {t} 시트(Class | Key | Type | Value)의 상수 선언과 로더입니다.");
            sb.AppendLine("using System.Collections.Generic;");
            sb.AppendLine("using System.Globalization;");
            sb.AppendLine("using UnityEngine;");
            sb.AppendLine();
            sb.AppendLine($"namespace {_param.@namespace}");
            sb.AppendLine("{");

            // 상수 선언
            sb.AppendLine("    /// <summary>");
            sb.AppendLine($"    /// {t} 상수. 값은 {t}InfoManager 가 로드할 때 채운다.");
            sb.AppendLine("    /// </summary>");
            sb.AppendLine($"    public static partial class {t}");
            sb.AppendLine("    {");
            for (int i = 0; i < schema.Classes.Count; i++)
            {
                var cls = schema.Classes[i];
                sb.AppendLine($"        public static partial class {cls.ClassName}");
                sb.AppendLine("        {");
                foreach (var k in cls.Keys)
                    sb.AppendLine($"            public static {k.CSharpType} {k.Key} {{ get; internal set; }}");
                sb.AppendLine("        }");
                if (i < schema.Classes.Count - 1)
                    sb.AppendLine();
            }
            sb.AppendLine("    }");
            sb.AppendLine();

            // 행 클래스
            sb.AppendLine("    /// <summary>");
            sb.AppendLine($"    /// {t} 시트의 한 행. 키는 \"Class.Key\" 이다.");
            sb.AppendLine("    /// </summary>");
            sb.AppendLine($"    public sealed class {t}Info : IInfoTemplate<string>, IInfoValidateChecker");
            sb.AppendLine("    {");
            foreach (var column in ConstColumns)
                sb.AppendLine($"        public string {column} {{ get; private set; }}");
            sb.AppendLine();
            sb.AppendLine("        string IInfoTemplate<string>.InfoKey => Class + \".\" + Key;");
            sb.AppendLine();
            sb.AppendLine("        void IInfoTemplate<string>.Deserialize(InfoRow row)");
            sb.AppendLine("        {");
            foreach (var column in ConstColumns)
                sb.AppendLine($"            {column} = row.Get<string>(\"{column}\");");
            sb.AppendLine("        }");
            sb.AppendLine();
            sb.AppendLine("        /// <summary>Value 가 이 행의 Type 으로 읽히는지 검사한다.</summary>");
            sb.AppendLine("        public bool IsValidData()");
            sb.AppendLine("        {");
            sb.AppendLine("            if (TryParse(Type, Value, out _))");
            sb.AppendLine("                return true;");
            sb.AppendLine();
            sb.AppendLine($"            Debug.LogError($\"[{t}] 값을 {{Type}} 로 읽을 수 없습니다: {{Class}}.{{Key}} = '{{Value}}'\");");
            sb.AppendLine("            return false;");
            sb.AppendLine("        }");
            sb.AppendLine();
            sb.AppendLine("        public bool IsValidAfterLoad()");
            sb.AppendLine("        {");
            sb.AppendLine("            return true;");
            sb.AppendLine("        }");
            sb.AppendLine();
            sb.AppendLine($"        /// <summary>지원 타입: {string.Join(", ", ConstSupportedTypes)}</summary>");
            sb.AppendLine("        internal static bool TryParse(string type, string text, out object value)");
            sb.AppendLine("        {");
            sb.AppendLine("            switch (NormalizeType(type))");
            sb.AppendLine("            {");
            AppendConstParseCase(sb, "int", "int.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out var intValue)", "intValue");
            AppendConstParseCase(sb, "long", "long.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out var longValue)", "longValue");
            AppendConstParseCase(sb, "float", "float.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out var floatValue)", "floatValue");
            AppendConstParseCase(sb, "double", "double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out var doubleValue)", "doubleValue");
            AppendConstParseCase(sb, "bool", "bool.TryParse(text, out var boolValue)", "boolValue");
            sb.AppendLine("                case \"string\":");
            sb.AppendLine("                    value = text ?? string.Empty;");
            sb.AppendLine("                    return true;");
            sb.AppendLine("            }");
            sb.AppendLine();
            sb.AppendLine("            value = null;");
            sb.AppendLine("            return false;");
            sb.AppendLine("        }");
            sb.AppendLine();
            sb.AppendLine("        internal static string NormalizeType(string type) => (type ?? string.Empty).Trim().ToLowerInvariant();");
            sb.AppendLine("    }");
            sb.AppendLine();

            // 로더
            sb.AppendLine("    /// <summary>");
            sb.AppendLine($"    /// {t} 테이블 로딩. 행을 읽은 뒤 생성된 각 상수에 (Class, Key) 행의 Value 를 넣는다.");
            sb.AppendLine("    /// </summary>");
            sb.AppendLine($"    public partial class {t}InfoManager : InfoManagerBase<string, {t}Info>");
            sb.AppendLine("    {");
            sb.AppendLine("        private static readonly HashSet<string> GeneratedKeys = new HashSet<string>");
            sb.AppendLine("        {");
            foreach (var cls in schema.Classes)
            foreach (var k in cls.Keys)
                sb.AppendLine($"            \"{cls.ClassName}.{k.Key}\",");
            sb.AppendLine("        };");
            sb.AppendLine();
            sb.AppendLine($"        public override string TableName => \"{t}\";");
            sb.AppendLine();
            sb.AppendLine("        protected override void OnLoaded()");
            sb.AppendLine("        {");
            foreach (var cls in schema.Classes)
            foreach (var k in cls.Keys)
                sb.AppendLine($"            {t}.{cls.ClassName}.{k.Key} = GetValue<{k.CSharpType}>(\"{cls.ClassName}\", \"{k.Key}\", \"{k.CSharpType}\");");
            sb.AppendLine();
            sb.AppendLine("            foreach (var key in _infos.Keys)");
            sb.AppendLine("            {");
            sb.AppendLine("                if (!GeneratedKeys.Contains(key))");
            sb.AppendLine($"                    Debug.LogWarning($\"[{t}] 코드에 없는 값입니다: {{key}} (코드 재생성 필요)\");");
            sb.AppendLine("            }");
            sb.AppendLine("        }");
            sb.AppendLine();
            sb.AppendLine("        /// <summary>(Class, Key) 행의 Value 를 코드에 선언된 타입으로 읽는다. 없거나 읽을 수 없으면 기본값.</summary>");
            sb.AppendLine("        private T GetValue<T>(string className, string key, string type)");
            sb.AppendLine("        {");
            sb.AppendLine("            var fullKey = className + \".\" + key;");
            sb.AppendLine("            if (!_infos.TryGetValue(fullKey, out var info))");
            sb.AppendLine("            {");
            sb.AppendLine($"                Debug.LogError($\"[{t}] 값이 없습니다: {{fullKey}} (행이 없거나 검사 실패)\");");
            sb.AppendLine("                return default;");
            sb.AppendLine("            }");
            sb.AppendLine();
            sb.AppendLine($"            if ({t}Info.NormalizeType(info.Type) != type)");
            sb.AppendLine($"                Debug.LogWarning($\"[{t}] 타입이 다릅니다: {{fullKey}} 시트={{info.Type}} 코드={{type}} (코드 재생성 필요)\");");
            sb.AppendLine();
            sb.AppendLine($"            if ({t}Info.TryParse(type, info.Value, out var value))");
            sb.AppendLine("                return (T)value;");
            sb.AppendLine();
            sb.AppendLine($"            Debug.LogError($\"[{t}] 값을 {{type}} 로 읽을 수 없습니다: {{fullKey}} = '{{info.Value}}'\");");
            sb.AppendLine("            return default;");
            sb.AppendLine("        }");
            sb.AppendLine("    }");
            sb.AppendLine("}");
            return sb.ToString();
        }

        private static void AppendConstParseCase(StringBuilder sb, string type, string tryParse, string variable)
        {
            sb.AppendLine($"                case \"{type}\":");
            sb.AppendLine($"                    if ({tryParse})");
            sb.AppendLine("                    {");
            sb.AppendLine($"                        value = {variable};");
            sb.AppendLine("                        return true;");
            sb.AppendLine("                    }");
            sb.AppendLine("                    break;");
        }

        // ============================================================
        // Helpers
        // ============================================================

        private static void AppendAutoGeneratedHeader(StringBuilder sb, string note)
        {
            sb.AppendLine("// ============================================================");
            sb.AppendLine("// <auto-generated> TableAutomationTool");
            sb.AppendLine($"// {note}");
            sb.AppendLine("// ============================================================");
            sb.AppendLine();
        }

        private static void AppendOnceHeader(StringBuilder sb)
        {
            sb.AppendLine("// ============================================================");
            sb.AppendLine($"// Date : {DateTime.Now:yyyy-MM-dd}");
            sb.AppendLine("// TableAutomationTool 이 최초 1회 생성한 파일입니다. 이후 재생성되지 않으므로 자유롭게 수정합니다.");
            sb.AppendLine("// ============================================================");
            sb.AppendLine();
        }

        private static void WriteAlways(string path, string content)
        {
            File.WriteAllText(path, content, new UTF8Encoding(false));
            Logger.Instance.Log($"[CSharpInfoGenerator] Generated: {path}");
        }

        private static void WriteIfMissing(string path, string content)
        {
            if (File.Exists(path))
            {
                Logger.Instance.Log($"[CSharpInfoGenerator] Skip (already exists): {path}");
                return;
            }

            File.WriteAllText(path, content, new UTF8Encoding(false));
            Logger.Instance.Log($"[CSharpInfoGenerator] Generated (once): {path}");
        }

        private static bool TryReadTable(string binaryFilePath, out TableSchema table)
        {
            table = null!;

            if (!File.Exists(binaryFilePath))
            {
                Logger.Instance.Error($"[CSharpInfoGenerator] Binary file not found: {binaryFilePath}");
                return false;
            }

            var schema = BinarySchema.ReadFromBytes(File.ReadAllBytes(binaryFilePath));
            if (schema.ColumnCount == 0)
            {
                Logger.Instance.Error($"[CSharpInfoGenerator] Binary schema is empty: {binaryFilePath}");
                return false;
            }

            var columns = schema.Columns
                .Select(kvp => new ColumnSchema(kvp.Key, ConvertToCSharpType(kvp.Value), ToParameterName(kvp.Key)))
                .ToList();

            table = new TableSchema(Path.GetFileNameWithoutExtension(binaryFilePath), columns);
            return true;
        }

        private static string ToParameterName(string columnName)
        {
            var name = char.ToLowerInvariant(columnName[0]) + columnName.Substring(1);
            return CSharpKeywords.Contains(name) ? "@" + name : name;
        }

        /// <summary>
        /// Binary 타입 문자열을 C# 타입으로 변환한다. 매핑되지 않는 이름(UserEnum 등)은 그대로 쓴다.
        /// </summary>
        private static string ConvertToCSharpType(string typeString)
        {
            var normalizedType = typeString.Contains(',') ? typeString.Split(',')[0].Trim() : typeString;
            if (normalizedType.StartsWith("System."))
                normalizedType = normalizedType.Substring("System.".Length);

            if (normalizedType.EndsWith("[]"))
                return ConvertToCSharpType(normalizedType.Substring(0, normalizedType.Length - 2)) + "[]";

            return normalizedType switch
            {
                "Int16" or "short" => "short",
                "Int32" or "int" => "int",
                "Int64" or "long" => "long",
                "Single" or "float" => "float",
                "Double" or "double" => "double",
                "String" or "string" => "string",
                "Boolean" or "bool" => "bool",
                "DateTime" => "DateTime",
                _ => normalizedType
            };
        }

        private static bool IsConstTable(string tableName) =>
            string.Equals(tableName, ConstTableName, StringComparison.OrdinalIgnoreCase);

        /// <summary>
        /// Const 테이블 행을 읽어 Class 별 Key 목록을 만든다. 코드로 쓸 수 없는 행은 경고 후 건너뛴다.
        /// 같은 Class.Key 가 여러 행이면 클라이언트 로드와 같게 Value 가 Type 으로 읽히는 첫 행을 쓴다.
        /// (클라이언트는 검사 실패 행을 버린 뒤 첫 행만 남기고, 남은 중복에는 중복 키 오류를 낸다)
        /// </summary>
        private static bool TryReadConstTable(string binaryFilePath, out ConstTableSchema schema)
        {
            schema = null!;
            if (!File.Exists(binaryFilePath))
            {
                Logger.Instance.Error($"[CSharpInfoGenerator] Binary file not found: {binaryFilePath}");
                return false;
            }

            var bytes = File.ReadAllBytes(binaryFilePath);
            var tableName = Path.GetFileNameWithoutExtension(binaryFilePath);
            var binaryColumns = BinarySchema.ReadFromBytes(bytes).Columns;
            var missingColumns = ConstColumns.Where(c => !binaryColumns.ContainsKey(c)).ToList();
            if (missingColumns.Count > 0)
            {
                Logger.Instance.Error($"[CSharpInfoGenerator] Const table needs columns {string.Join(" | ", ConstColumns)}, missing: {string.Join(", ", missingColumns)} ({binaryFilePath})");
                return false;
            }

            var classOrder = new List<string>();
            var keysByClass = new Dictionary<string, List<ConstKeySchema>>(StringComparer.Ordinal);
            var validValueKeys = new HashSet<string>(StringComparer.Ordinal);

            foreach (var row in new BinaryParser.BinaryReader().ReadFromBytes(bytes))
            {
                // Class/Key 는 클라이언트 키("Class.Key")와 같아야 하므로 다듬지 않는다. Type 은 클라이언트도 Trim·소문자로 비교한다.
                var cls = GetConstCell(row, "Class");
                var key = GetConstCell(row, "Key");
                var type = GetConstCell(row, "Type").Trim().ToLowerInvariant();
                var value = GetConstCell(row, "Value");

                // 중첩 클래스·멤버 이름이 바깥 타입과 같으면 컴파일 오류(CS0542)라 함께 거른다.
                if (!IsValidCSharpIdentifier(cls) || cls == tableName)
                {
                    Logger.Instance.Warning($"[CSharpInfoGenerator] Invalid Class '{cls}' (Key '{key}') in {tableName}, row skipped.");
                    continue;
                }
                if (!IsValidCSharpIdentifier(key) || key == cls)
                {
                    Logger.Instance.Warning($"[CSharpInfoGenerator] Invalid Key '{key}' (Class '{cls}') in {tableName}, row skipped.");
                    continue;
                }
                if (!ConstSupportedTypes.Contains(type))
                {
                    Logger.Instance.Warning($"[CSharpInfoGenerator] Unsupported Type '{type}' for {cls}.{key} in {tableName} (supported: {string.Join(", ", ConstSupportedTypes)}), row skipped.");
                    continue;
                }

                // 선언은 남기고 경고만 한다. 클라이언트는 이 행을 검사 실패로 버리고 상수에 기본값을 넣는다.
                var isValidValue = IsValidConstValue(type, value);
                if (!isValidValue)
                    Logger.Instance.Warning($"[CSharpInfoGenerator] Value '{value}' of {cls}.{key} in {tableName} is not {type}. Client load will reject this row.");

                if (!keysByClass.TryGetValue(cls, out var keys))
                {
                    keysByClass[cls] = keys = new List<ConstKeySchema>();
                    classOrder.Add(cls);
                }

                var fullKey = cls + "." + key;
                var index = keys.FindIndex(e => e.Key == key);
                if (index >= 0)
                {
                    Logger.Instance.Warning($"[CSharpInfoGenerator] Duplicate key '{fullKey}' in {tableName}. The first row with a valid Value is used, as in client load.");
                    if (isValidValue && validValueKeys.Add(fullKey))
                        keys[index] = new ConstKeySchema(key, type);
                    continue;
                }

                keys.Add(new ConstKeySchema(key, type));
                if (isValidValue)
                    validValueKeys.Add(fullKey);
            }

            // 등록부(GenerateDataManager)는 .bin 이 있으면 {T}InfoManager 를 참조하므로, 행이 없어도 빈 상수로 생성한다.
            if (classOrder.Count == 0)
                Logger.Instance.Warning($"[CSharpInfoGenerator] No valid const entries in {binaryFilePath}, generating empty {tableName}.");

            schema = new ConstTableSchema(tableName, classOrder.Select(c => new ConstClassSchema(c, keysByClass[c])).ToList());
            return true;
        }

        private static string GetConstCell(Dictionary<string, object> row, string column) =>
            row.TryGetValue(column, out var value) ? value as string ?? "" : "";

        /// <summary>생성 코드의 {T}Info.TryParse 와 같은 규칙으로 Value 를 검사한다.</summary>
        private static bool IsValidConstValue(string type, string value) => type switch
        {
            "int" => int.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out _),
            "long" => long.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out _),
            "float" => float.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out _),
            "double" => double.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out _),
            "bool" => bool.TryParse(value, out _),
            _ => true,
        };

        private static bool IsValidCSharpIdentifier(string name)
        {
            if (string.IsNullOrEmpty(name) || CSharpKeywords.Contains(name) || CSharpReservedTokens.Contains(name)) return false;
            if (!char.IsLetter(name[0]) && name[0] != '_') return false;
            return name.Skip(1).All(c => char.IsLetterOrDigit(c) || c == '_');
        }

        private sealed record ConstKeySchema(string Key, string CSharpType);
        private sealed record ConstClassSchema(string ClassName, List<ConstKeySchema> Keys);
        private sealed record ConstTableSchema(string TableName, List<ConstClassSchema> Classes);

        private sealed record ColumnSchema(string Name, string Type, string ParameterName);

        private sealed record TableSchema(string Name, List<ColumnSchema> Columns)
        {
            public string KeyType => Columns[0].Type;
        }
    }
}
